mapper.select:
SELECT -- education 테이블 edu.EDUCATION_NO AS EDUCATION_NO, edu.RESUME_NO AS EDUCATION_RESUME_NO, edu.HIGHEST_EDUCATION_CODE AS HIGHEST_EDUCATION_CODE, edu.SCHOOL_NAME AS SCHOOL_NAME, edu.GRADUATE_YN AS GRADUATE_YN, edu.TRANSFER_YN AS TRANSFER_YN, TO_CHAR(TO_DATE(edu.ENTRANCE_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS ENTRANCE_DATE, TO_CHAR(TO_DATE(edu.GRADUATE_DATE, 'YYYYMMDD'), 'YYYY-MM-DD') AS GRADUATE_DATE, edu.LOCATION AS EDUCATION_LOCATION, edu.DEPARTMENT_CODE AS DEPARTMENT_CODE, edu.DELETE_DATE AS EDUCATION_DELETE_DATE,
-- specialty 테이블 spc.EDUCATION_NO AS SPECIALTY_EDUCATION_NO, spc.RESUME_NO AS SPECIALTY_RESUME_NO, spc.MAIN_MAJOR AS MAIN_MAJOR, spc.SUB_MAJOR AS SUB_MAJOR, spc.SUB_MAJOR_CODE AS SUB_MAJOR_CODE, spc.DELETE_DATE AS SPECIALTY_DELETE_DATE
FROM education edu LEFT JOIN specialty spc ON edu.EDUCATION_NO = spc.EDUCATION_NO WHERE edu.RESUME_NO = #{resumeNo}

mapper.insert:

    SELECT
        'EDCT'||
        LPAD(NVL(TO_NUMBER(SUBSTR(MAX(EDUCATION_NO), LENGTH('EDCT' ) + 1)), 0) + 1, 6, '0')
    FROM EDUCATION
   WHERE RESUME_NO = #{resumeNo}

INSERT INTO EDUCATION (
	EDUCATION_NO
	, RESUME_NO
	, HIGHEST_EDUCATION_CODE
	, SCHOOL_NAME
	, GRADUATE_YN
	, TRANSFER_YN
	, ENTRANCE_DATE
	, GRADUATE_DATE
	, LOCATION
	, DEPARTMENT_CODE
) VALUES (
	#{educationNo}
	, #{resumeNo}
	, #{highestEducationCode}
	, #{schoolName}
	, #{graduateYn}
	, #{transferYn}
	, REPLACE(#{entranceDate}, '-', '')
	, REPLACE(#{graduateDate}, '-', '')
	, #{location}
	, #{departmentCode}
)

mapper.update:
UPDATE EDUCATION 
   SET HIGHEST_EDUCATION_CODE = #{highestEducationCode}
   	   , SCHOOL_NAME = #{schoolName}
   	   , GRADUATE_YN = #{graduateYn}
   	   , TRANSFER_YN = #{transferYn}
   	   , ENTRANCE_DATE = REPLACE(#{entranceDate}, '-', '')
   	   , GRADUATE_DATE = REPLACE(#{graduateDate}, '-', '')
   	   , LOCATION = #{location}
   	   , DEPARTMENT_CODE = #{departmentCode} 
 WHERE EDUCATION_NO = #{educationNo} 
   AND RESUME_NO = #{resumeNo}
